create table category (is_active boolean not null, sort_order integer not null, id bigint generated by default as identity, parent_id bigint, path varchar(500), name varchar(255) not null, slug varchar(255) not null unique, primary key (id));
create table customer (is_active boolean not null, points_balance integer not null, total_spent numeric(14,2) not null, created_at timestamp(6) not null, id bigint generated by default as identity, loyalty_level varchar(10) not null check ((loyalty_level in ('NONE','BRONZE','SILVER','GOLD'))), phone varchar(20), email varchar(255) unique, name varchar(255) not null, primary key (id));
create table employee (is_active boolean not null, pay_rate numeric(12,2) not null, fired_at timestamp(6), hired_at timestamp(6) not null, id bigint generated by default as identity, pay_type varchar(10) not null check ((pay_type in ('HOURLY','MONTHLY'))), employee_role varchar(255) not null check ((employee_role in ('CASHIER','MANAGER','WAREHOUSE'))), name varchar(255) not null, primary key (id));
create table loyalty_transaction (points integer not null, created_at timestamp(6) not null, customer_id bigint not null, expires_at timestamp(6), id bigint generated by default as identity, sales_order_id bigint, loyalty_transaction_type varchar(20) not null check ((loyalty_transaction_type in ('EARN','REDEEM','EXPIRE','ADJUSTMENT'))), primary key (id));
create table payment (amount numeric(14,2) not null, id bigint generated by default as identity, paid_at timestamp(6), sales_order_id bigint not null, payment_method varchar(20) not null check ((payment_method in ('CASH','CARD'))), payment_status varchar(20) not null check ((payment_status in ('PENDING','COMPLETED','FAILED','REFUNDED'))), primary key (id));
create table payroll (amount numeric(12,2) not null, hours_worked numeric(8,2) not null, period_end date not null, period_start date not null, rate_snapshot numeric(12,2) not null, employee_id bigint not null, id bigint generated by default as identity, paid_at timestamp(6), primary key (id), constraint uq_payroll_period unique (employee_id, period_start, period_end));
create table price_history (price numeric(12,2) not null, id bigint generated by default as identity, product_id bigint not null, valid_from timestamp(6) not null, valid_to timestamp(6), primary key (id));
create table product (cost_price numeric(12,2) not null, current_price numeric(12,2) not null, is_active boolean not null, category_id bigint not null, id bigint generated by default as identity, unit varchar(10) not null check ((unit in ('PCS','KG','L'))), barcode varchar(14) unique, sku varchar(50) not null unique, description varchar(2000), name varchar(255) not null, primary key (id));
create table purchase_order (created_at timestamp(6) not null, expected_at timestamp(6) not null, id bigint generated by default as identity, received_at timestamp(6), supplier_id bigint not null, status varchar(20) not null check ((status in ('DRAFT','ORDERED','RECEIVED','CANCELLED'))), primary key (id));
create table purchase_order_item (quantity numeric(14,3) not null, unit_cost numeric(12,2) not null, id bigint generated by default as identity, product_id bigint not null, purchase_order_id bigint not null, primary key (id));
create table sales_order (points_earned integer, points_redeemed integer, total numeric(14,2) not null, created_at timestamp(6) not null, customer_id bigint, employee_id bigint not null, id bigint generated by default as identity, status varchar(20) not null check ((status in ('NEW','PAID','COMPLETED','CANCELLED'))), primary key (id));
create table sales_order_item (quantity numeric(14,3) not null, unit_price numeric(12,2) not null, id bigint generated by default as identity, product_id bigint not null, sales_order_id bigint not null, primary key (id));
create table shift (employee_id bigint not null, end_at timestamp(6), id bigint generated by default as identity, start_at timestamp(6) not null, primary key (id));
create table sim_clock (is_running boolean not null, speed_multiplier numeric(8,2) not null, id bigint not null, sim_time timestamp(6) not null, primary key (id));
create table sim_config (config_key varchar(100) not null, config_value varchar(500) not null, primary key (config_key));
create table sim_event (created_at timestamp(6) not null, id bigint generated by default as identity, sim_time timestamp(6) not null, type varchar(30) not null check ((type in ('CUSTOMER_ARRIVED','SALE_COMPLETED','SALE_CANCELLED','PURCHASE_ORDERED','PURCHASE_RECEIVED','STOCK_LOW','SHIFT_STARTED','SHIFT_ENDED','PAYROLL_RUN','POINTS_EXPIRED','PRICE_CHANGED'))), payload jsonb, primary key (id));
create table stock (quantity numeric(14,3) not null, reorder_level numeric(14,3) not null, product_id bigint not null, version bigint not null, primary key (product_id));
create table stock_movement (quantity numeric(14,3) not null, created_at timestamp(6) not null, id bigint generated by default as identity, product_id bigint not null, ref_id bigint, ref_type varchar(20) check ((ref_type in ('PURCHASE_ORDER','SALES_ORDER'))), type varchar(20) not null check ((type in ('PURCHASE','SALE','WRITE_OFF','RETURN'))), primary key (id));
create table supplier (lead_time_days integer not null, reliability integer not null, id bigint generated by default as identity, contact varchar(255) not null, name varchar(255) not null, primary key (id));
create table user_account (is_enabled boolean not null, created_at timestamp(6) not null, employee_id bigint unique, id bigint generated by default as identity, user_role varchar(20) not null check ((user_role in ('ADMIN','MANAGER','CASHIER','WAREHOUSE'))), username varchar(50) not null unique, password_hash varchar(100) not null, primary key (id));
create index idx_loyalty_customer_time on loyalty_transaction (customer_id, created_at);
create index idx_sim_event_time on sim_event (sim_time);
create index idx_sim_event_type_time on sim_event (type, sim_time);
create index idx_movement_product_time on stock_movement (product_id, created_at);
